const CABLES={copper:'UTP / RJ45',sm:'Fiber · Single-mode',mm:'Fiber · Multimode'},NODE_W=244,NODE_H=88;
let state,selected=null,selectedLink=null,history=[],future=[],zoom=1,pan={x:0,y:0},brand='All',drag=null,physicalId=null,face='front',physicalScale=1,draft=null,toastTimer,category='All',tool='select',cableStart=null,selectedLabel=null,labelDraft=null,deviceTab='physical',physicalVisual='photo',skipCanvasClick=false,exportBusy=false;
