const displayModel=id=>window.NOAH_AUDIENCE.external(state)?window.NOAH_AUDIENCE.models(catalog).find(m=>m.id===id):models.get(id);
const getPort=(did,pid,project=state)=>{const d=getDevice(did,project);return d&&window.NOAH_GEOMETRY.port(models,d,pid);};
