const linkDefaults=l=>({role:'standard',shape:'curved',color:'',enabled:true,showLabel:true,vlanMode:'trunk',mtu:9216,...l});
const blankProject=(name='Untitled project')=>({format:'noah-topology',version:3,linkGridSize:20,id:uid('project'),name,metadata:{createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()},devices:[],links:[],labels:[],groups:[]});
