  $('filters').innerHTML=['All',...new Set(catalog.filter(m=>!m.hidden).map(m=>m.brand))].map(b=>`<button data-brand="${b}" aria-pressed="${brand===b}" class="${brand===b?'active':''}">${b==='All'?'ทุก Brand':b}</button>`).join('');
  const shown=catalog.filter(m=>!m.hidden&&(category==='All'||(category==='pe'?m.topologyOnly:m.category===category))&&(brand==='All'||m.brand===brand)&&(!query||(m.name+' '+m.summary+' '+m.category+' '+(m.deviceRole||'')).toLowerCase().includes(query))&&(!editor||editor.libraryVisible(m.id)));
