function edgePath(a,b){const ax=a.x+NODE_W,ay=a.y+NODE_H/2,bx=b.x,by=b.y+NODE_H/2,forward=bx>=ax,x1=forward?ax:a.x+NODE_W/2,y1=forward?ay:a.y+NODE_H,x2=forward?bx:b.x+NODE_W/2,y2=forward?by:b.y,mid=forward?(x1+x2)/2:(y1+y2)/2;return {path:forward?`M${x1},${y1} C${mid},${y1} ${mid},${y2} ${x2},${y2}`:`M${x1},${y1} C${x1},${mid} ${x2},${mid} ${x2},${y2}`,x:(x1+x2)/2,y:(y1+y2)/2};}
