  if(!perform(()=>{const value={...(input.zIndex!==undefined?{zIndex:input.zIndex}:{}),id,x:input.x,y:input.y,text:input.text,fontSize:input.fontSize,color:input.color,bold:!!input.bold,kind:input.kind||'text',background:input.background||'transparent',align:input.align||'left',backgroundOpacity:input.backgroundOpacity??1};if(!Number.isFinite(value.backgroundOpacity)||value.backgroundOpacity<0||value.backgroundOpacity>1)throw new Error('ความโปร่งใสของ Label ไม่ถูกต้อง');if(!['text','region','shape'].includes(value.kind)||!['left','center','right'].includes(value.align)||value.background!=='transparent'&&!/^#[\da-f]{6}$/i.test(value.background))throw new Error('รูปแบบ Label ไม่ถูกต้อง');if(value.kind==='region'||value.kind==='shape'){if(!Number.isFinite(input.width)||!Number.isFinite(input.height)||input.width<(value.kind==='shape'?32:80)||input.height<(value.kind==='shape'?32:60)||input.width>10000||input.height>10000)throw new Error('ขนาดกรอบพื้นที่ไม่ถูกต้อง');value.width=input.width;value.height=input.height;}if(value.kind==='shape'){if(!window.NOAH_ELEMENTS.valid(input))throw new Error('รูปทรงไม่ถูกต้อง');value.shape=input.shape;value.stroke=input.stroke;value.strokeWidth=input.strokeWidth;const opacity=input.opacity??(i>=0?state.labels[i].opacity:undefined);if(opacity!==undefined){if(!Number.isFinite(opacity)||opacity<0||opacity>1)throw new Error('ความโปร่งแสง Element ไม่ถูกต้อง');value.opacity=opacity;}}if(i<0)state.labels.push(value);else state.labels[i]=value;selectedLabel=id;selected=null;selectedLink=null;}))throw new Error('บันทึก Text Label ไม่สำเร็จ');return id;
